-- personalizacao-servidor.sql
-- Cria as tabelas de personalizacao/modulos por empresa (company_settings,
-- company_modules) no banco do tenant em producao e semeia os valores padrao.
-- Mesmo padrao do bazar-servidor.sql: aplicar manualmente no banco do servidor.
--
-- Aplicar:
--   docker compose exec -T db sh -c 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < personalizacao-servidor.sql
--
-- Idempotente: pode rodar mais de uma vez sem erro.

BEGIN;

CREATE TABLE IF NOT EXISTS company_settings (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "LogoPath" varchar(500),
    "LogoFilename" varchar(255),
    "PrimaryColor" varchar(7) NOT NULL,
    "SecondaryColor" varchar(7) NOT NULL,
    "DefaultTheme" varchar(10) NOT NULL DEFAULT 'Dark',
    "DisplayName" varchar(100) NOT NULL,
    "UpdatedAt" timestamptz NOT NULL,
    "UpdatedBy" integer,
    CONSTRAINT "PK_company_settings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_company_settings_Empresas_EmpresaId"
        FOREIGN KEY ("EmpresaId") REFERENCES "Empresas"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_company_settings_Usuarios_UpdatedBy"
        FOREIGN KEY ("UpdatedBy") REFERENCES "Usuarios"("Id") ON DELETE SET NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_company_settings_EmpresaId" ON company_settings ("EmpresaId");
CREATE INDEX IF NOT EXISTS "IX_company_settings_UpdatedBy" ON company_settings ("UpdatedBy");

CREATE TABLE IF NOT EXISTS company_modules (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpresaId" integer NOT NULL,
    "ModuleKey" varchar(50) NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "UpdatedAt" timestamptz NOT NULL,
    "UpdatedBy" integer,
    CONSTRAINT "PK_company_modules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_company_modules_Empresas_EmpresaId"
        FOREIGN KEY ("EmpresaId") REFERENCES "Empresas"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_company_modules_Usuarios_UpdatedBy"
        FOREIGN KEY ("UpdatedBy") REFERENCES "Usuarios"("Id") ON DELETE SET NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_company_modules_EmpresaId_ModuleKey" ON company_modules ("EmpresaId","ModuleKey");
CREATE INDEX IF NOT EXISTS "IX_company_modules_UpdatedBy" ON company_modules ("UpdatedBy");

-- Config padrao por empresa (so insere se ainda nao existir).
INSERT INTO company_settings ("EmpresaId","PrimaryColor","SecondaryColor","DefaultTheme","DisplayName","UpdatedAt")
SELECT e."Id", '#FACC15', '#1F2937', 'Dark', e."Nome", now()
FROM "Empresas" e
WHERE NOT EXISTS (SELECT 1 FROM company_settings cs WHERE cs."EmpresaId" = e."Id");

-- Todos os modulos habilitados por empresa (so insere os que faltam).
INSERT INTO company_modules ("EmpresaId","ModuleKey","IsEnabled","UpdatedAt")
SELECT e."Id", m.k, true, now()
FROM "Empresas" e
CROSS JOIN (VALUES
    ('inicio'),('configuracoes'),('usuarios'),('empresas'),('bazar'),
    ('repasses'),('caixa'),('catalogo'),('condicional'),('vendas'),
    ('compras'),('estoque'),('fiscal'),('produtos'),('clientes'),
    ('fornecedores'),('relatorios')
) AS m(k)
WHERE NOT EXISTS (
    SELECT 1 FROM company_modules cm
    WHERE cm."EmpresaId" = e."Id" AND cm."ModuleKey" = m.k
);

-- Registra a migration como aplicada (se a tabela de historico existir),
-- para manter o EF consistente caso use dotnet ef no futuro.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = '__EFMigrationsHistory') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId","ProductVersion")
    SELECT '20260523184227_AdicionarPersonalizacaoEmpresa','9.0.0'
    WHERE NOT EXISTS (
        SELECT 1 FROM "__EFMigrationsHistory"
        WHERE "MigrationId" = '20260523184227_AdicionarPersonalizacaoEmpresa'
    );
  END IF;
END $$;

COMMIT;
